public final class Config {
    // volatile is not an optimisation. It prevents publication of a
    // half-constructed object: writes inside the constructor cannot
    // be reordered past this store.
    private static volatile Config INSTANCE;

    private final Map<String, String> values;

    private Config(Map<String, String> values) {
        if (INSTANCE != null) {
            throw new IllegalStateException("use getInstance()");
        }
        this.values = Map.copyOf(values);
    }

    public static Config getInstance() {
        Config local = INSTANCE; // one volatile read on fast path
        if (local == null) {
            synchronized (Config.class) {
                if (INSTANCE == null) {
                    INSTANCE = new Config(loadFromDisk());
                }
                local = INSTANCE;
            }
        }
        return local;
    }

    // readResolve stops deserialization from minting a second instance.
    private Object readResolve() { return getInstance(); }

    private static Map<String, String> loadFromDisk() { return Map.of(); }
    public String get(String k) { return values.get(k); }
}

// Prefer this for lazy singletons in Java. No locks in your code,
// thread safety comes from class initialisation guarantees (JLS 12.4.2).
public final class Registry {
    private Registry() {}

    private static class Holder {
        static final Registry INSTANCE = new Registry();
    }

    public static Registry getInstance() {
        return Holder.INSTANCE;
    }
}

// Prefer this when you want serialization + reflection resistance for free.
// Enum constants are instantiated once by the JVM and cannot be
// reflectively constructed or deserialized into duplicates.
enum AppConfig {
    INSTANCE;
    private final Map<String, String> values = new ConcurrentHashMap<>();
    public String get(String k) { return values.get(k); }
    public void set(String k, String v) { values.put(k, v); }
}
